<script setup>
import { onMounted, reactive, ref } from 'vue'
const props = defineProps({ api: { type: Function, required: true }, download: { type: Function, required: true } })
const items = ref([]), plans = ref([]), loading = ref(false), saving = ref(false), error = ref(''), query = ref(''), page = ref(1), modal = ref(false), formError = ref('')
const periods = [['monthly','月付'],['quarterly','季付'],['half_yearly','半年付'],['yearly','年付'],['two_yearly','两年付'],['three_yearly','三年付'],['onetime','一次性'],['reset_traffic','流量重置']]
const form = reactive({ id:null,name:'',code:'',type:1,value:0,started_at:'',ended_at:'',limit_use:'',limit_use_with_user:'',generate_count:1,limit_plan_ids:[],limit_period:[] })
const dateValue = value => { if(!value)return ''; const d=new Date(Number(value)*1000); const p=n=>String(n).padStart(2,'0'); return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}` }
const timestamp = value => value ? Math.floor(new Date(value).getTime()/1000) : null
const amount = coupon => Number(coupon.type) === 1 ? `¥${(Number(coupon.value||0)/100).toFixed(2)}` : `${coupon.value}%`
const when = value => value ? new Date(Number(value)*1000).toLocaleString('zh-CN') : '—'
async function load(p=1) { loading.value=true; error.value=''; page.value=p; try { const q=new URLSearchParams({current:String(p),pageSize:'25'}); if(query.value.trim()){q.set('filter[0][id]','code');q.set('filter[0][value]',query.value.trim())} items.value=await props.api(`coupon/fetch?${q}`); if(!Array.isArray(items.value))items.value=[] } catch(e){error.value=e.message;items.value=[]} finally{loading.value=false} }
async function loadPlans(){try{plans.value=await props.api('plan/fetch')}catch{plans.value=[]}}
function blank(){Object.assign(form,{id:null,name:'',code:'',type:1,value:0,started_at:'',ended_at:'',limit_use:'',limit_use_with_user:'',generate_count:1,limit_plan_ids:[],limit_period:[]});formError.value=''}
function create(){blank();modal.value=true}
function edit(c){blank();Object.assign(form,{id:c.id,name:c.name||'',code:c.code||'',type:Number(c.type||1),value:Number(c.type)===1?Number(c.value||0)/100:Number(c.value||0),started_at:dateValue(c.started_at),ended_at:dateValue(c.ended_at),limit_use:c.limit_use??'',limit_use_with_user:c.limit_use_with_user??'',generate_count:1,limit_plan_ids:c.limit_plan_ids||[],limit_period:c.limit_period||[]});modal.value=true}
async function save(){saving.value=true;formError.value='';try{const body={id:form.id||undefined,name:form.name,code:form.code||undefined,type:Number(form.type),value:Number(form.type)===1?Math.round(Number(form.value)*100):Math.round(Number(form.value)),started_at:timestamp(form.started_at),ended_at:timestamp(form.ended_at),limit_use:form.limit_use===''?null:Number(form.limit_use),limit_use_with_user:form.limit_use_with_user===''?null:Number(form.limit_use_with_user),limit_plan_ids:form.limit_plan_ids.map(Number),limit_period:form.limit_period};if(!form.id&&Number(form.generate_count)>1){body.generate_count=Number(form.generate_count);await props.download('coupon/generate',{method:'POST',body},'xboard-coupons.csv')}else await props.api('coupon/generate',{method:'POST',body});modal.value=false;await load(page.value)}catch(e){formError.value=e.message}finally{saving.value=false}}
async function toggle(c){try{await props.api('coupon/show',{method:'POST',body:{id:c.id}});await load(page.value)}catch(e){error.value=e.message}}
async function remove(c){if(!window.confirm(`删除优惠券 ${c.code}？`))return;try{await props.api('coupon/drop',{method:'POST',body:{id:c.id}});await load(page.value)}catch(e){error.value=e.message}}
onMounted(()=>{load();loadPlans()})
</script>
<template>
<section class="content-view coupon-view"><div class="page-title-row"><div><p class="eyebrow">CUSTOMERS / DISCOUNTS</p><h1>优惠券<span class="title-period">.</span></h1><p class="page-subtitle">创建单张或批量生成优惠券，限定订阅和可用周期</p></div><button class="assign-order-button" @click="create">＋ 创建优惠券</button></div>
<div class="page-title-row coupon-toolbar"><span class="coupon-count">{{ items.length }} 条当前页记录</span><form class="user-search" @submit.prevent="load(1)"><input v-model="query" placeholder="按优惠券码搜索" /><button>搜索</button></form></div>
<div v-if="error" class="api-error"><span>!</span><div><b>优惠券操作失败</b><p>{{ error }}</p></div><button @click="load(page)">重试</button></div>
<div class="users-table-wrap"><div v-if="loading" class="table-state">正在读取优惠券…</div><div v-else-if="!items.length" class="table-state">暂无优惠券。</div><table v-else class="users-table coupon-table"><thead><tr><th>优惠券</th><th>优惠</th><th>有效期</th><th>使用情况</th><th>限制</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="c in items" :key="c.id"><td><b class="trade-code">{{ c.code }}</b><small class="order-id">{{ c.name }} · ID {{ c.id }}</small></td><td>{{ amount(c) }}</td><td>{{ when(c.started_at) }}<small class="order-id">至 {{ when(c.ended_at) }}</small></td><td>{{ c.used_count ?? 0 }} / {{ c.limit_use || '∞' }}</td><td>{{ c.limit_plan_ids?.length ? `套餐 ${c.limit_plan_ids.join(',')}` : '不限套餐' }}</td><td><button class="user-status status-button" :class="{disabled:!c.show}" @click="toggle(c)">{{ c.show?'可用':'已停用' }}</button></td><td><div class="row-actions"><button @click="edit(c)">编辑</button><button class="danger-action" @click="remove(c)">删除</button></div></td></tr></tbody></table></div>
<div class="table-pagination"><span>第 {{ page }} 页 · {{ items.length }} 张优惠券</span><div><button :disabled="page<=1||loading" @click="load(page-1)">← 上一页</button><button :disabled="items.length<25||loading" @click="load(page+1)">下一页 →</button></div></div><div class="footer-note"><span>XB CONTROL ROOM</span><span>批量生成将下载 CSV <i>·</i> 金额按元输入</span></div>
<div v-if="modal" class="modal-backdrop" @click.self="modal=false"><section class="user-modal coupon-modal" role="dialog" aria-modal="true"><header class="modal-header"><div><p class="eyebrow">DISCOUNTS / {{form.id?'EDIT':'CREATE'}}</p><h2>{{form.id?'编辑优惠券':'创建优惠券'}}</h2></div><button class="modal-close" @click="modal=false">×</button></header><form class="user-form" @submit.prevent="save"><label>优惠券名称<input v-model.trim="form.name" required /></label><label>优惠券码（空白自动生成）<input v-model.trim="form.code" :disabled="!form.id&&Number(form.generate_count)>1" /></label><div class="form-pair"><label>优惠类型<select v-model.number="form.type"><option :value="1">固定金额</option><option :value="2">折扣比例</option></select></label><label>{{form.type===1?'减免金额（元）':'折扣比例（%）'}}<input v-model.number="form.value" type="number" min="0" :max="form.type===2?100:undefined" step="0.01" required /></label></div><div class="form-pair"><label>开始时间<input v-model="form.started_at" type="datetime-local" required /></label><label>结束时间<input v-model="form.ended_at" type="datetime-local" required /></label></div><div class="form-pair"><label>总使用次数上限<input v-model.number="form.limit_use" type="number" min="1" placeholder="不限" /></label><label>每用户使用次数<input v-model.number="form.limit_use_with_user" type="number" min="1" placeholder="不限" /></label></div><label>适用套餐（不选表示全部）<select v-model="form.limit_plan_ids" multiple class="multi-select"><option v-for="plan in plans" :key="plan.id" :value="plan.id">{{plan.name}} · {{plan.id}}</option></select></label><div class="period-checks"><label v-for="[key,name] in periods" :key="key"><input v-model="form.limit_period" type="checkbox" :value="key" />{{name}}</label></div><label v-if="!form.id">批量生成数量<input v-model.number="form.generate_count" type="number" min="1" max="500" /></label><p v-if="formError" class="notice">{{formError}}</p><footer class="modal-footer"><button type="button" class="cancel-button" @click="modal=false">取消</button><button type="submit" class="save-button" :disabled="saving">{{saving?'处理中…':Number(form.generate_count)>1&&!form.id?'生成并下载 CSV':'保存优惠券'}}</button></footer></form></section></div>
</section>
</template>
